<template><AppShell tab="mine"><view class="profile-head"><view class="row"><button class="ui-button avatar-home" aria-label="查看我的个人主页" :disabled="openingHome" @click="openHome"><GameArt avatar :size="58" class="profile-avatar" :type="session.user?.avatar||'anime'" :src="session.user?.avatar?.startsWith('/')?session.user.avatar:''" /></button><view class="stack flex-1" @click="openHome"><text class="profile-name">{{session.user?.nickname||'登录，逛逛玩家集市'}}</text><PlayerBadges v-if="session.user" :shop-status="session.user.playerProfile?.shopStatus" :realname-status="session.user.playerProfile?.realnameStatus" /><text v-if="session.user" class="muted tiny">编号 {{session.user.userNo}} · IP属地：{{session.user.playerProfile?.ipProvince||'未知'}}</text><text v-else class="muted">发现道具，管理自己的交易</text></view><button class="ui-button icon-button" aria-label="帮助与客服" @click="go('account/index',{type:'help'})"><AppIcon class="app-icon" name="headset" /></button><button class="ui-button icon-button" aria-label="设置" @click="open('account/index',{type:'settings'})"><AppIcon class="app-icon" name="settings" /></button></view><view v-if="site?.profileBannerImage" class="profile-banner"><image class="profile-custom-banner" :src="contentImage(site.profileBannerImage)" mode="aspectFill" /></view><view v-else class="profile-banner"><GameArt variant="banner" type="crown" /><view class="profile-banner-copy"><view class="bold"><text>{{site?.profileBannerTitle||'每一件装备，找到新主人'}}</text></view><text class="tiny">{{site?.profileBannerSubtitle||'和平精英 · 玩家自主交易'}}</text></view></view><view class="stats"><button class="ui-button" v-for="stat in stats" :key="stat.type" @click="open('account/index',{type:stat.type})"><text>{{session.user?.[stat.key]||0}}</text><text>{{stat.label}}</text></button></view></view><view class="pad"><view v-if="session.user" class="benefit-cards">
<view class="card benefit-details">
<button class="ui-button benefit-card growth-card" aria-label="查看成长值明细" @click="open('growth/index')">
  <view class="row between"><text class="benefit-label">成长值</text><text class="benefit-level">Lv.{{profile.level||1}}</text><AppIcon name="chevron" :size="12" /></view>
  <text class="benefit-caption">{{profile.growthPoints||0}}{{profile.nextLevelPoints!=null?' / '+profile.nextLevelPoints:''}}</text>
  <view v-if="profile.growthProgress!=null" class="step-line benefit-progress"><view :style="{width:Math.max(0,Math.min(100,Number(profile.growthProgress)||0))+'%'}" /></view>
  <text v-if="!profile.growthRulesReady||profile.nextLevelPoints==null" class="benefit-hint">{{!profile.growthRulesReady?'等级规则待配置':'已达当前最高等级'}}</text>
</button>
<button class="ui-button benefit-card membership-card" aria-label="查看会员信息" @click="open('growth/index',{section:'membership'})">
  <view class="row between"><text class="benefit-label">会员</text><text class="benefit-value" :class="{'member-active':profile.membershipActive}">{{profile.membershipActive?'会员':'非会员'}}</text><AppIcon name="chevron" :size="12" /></view>
  <text class="benefit-caption">{{profile.membershipActive?membershipDate+' 到期':'当前未开通'}}</text>
</button>
</view>
<button class="ui-button card wallet-card" aria-label="查看我的钱包" @click="open('wallet/index')">
  <view class="row between"><text class="benefit-label">我的钱包</text><AppIcon name="chevron" :size="12" /></view>
  <text class="wallet-number">¥ {{money(session.user.balanceCents||0)}}</text>
  <text class="benefit-hint">查看账单</text>
</button>
</view><view class="card"><view class="section-heading"><text class="field-label">我的交易</text><button class="ui-button section-more" @click="open('orders/index')">查看全部<AppIcon class="app-icon" name="chevron" :size="12" /></button></view><view class="transactions"><button class="ui-button" v-for="t in transactions" :key="t.label" @click="open(t.path,t.params)"><AppIcon class="app-icon" :name="t.icon" :size="28" /><text>{{t.label}}</text></button></view></view><view class="card"><view class="section-heading"><text class="field-label">积分与活动</text></view><view class="reward-entries"><button class="ui-button reward-entry" aria-label="我的积分" @click="open('rewards/points')"><image class="reward-entry-icon" src="/static/rewards/points.png" mode="aspectFit" aria-hidden="true" /><text>我的积分</text></button><button class="ui-button reward-entry" aria-label="兑换记录" @click="open('rewards/orders')"><image class="reward-entry-icon" src="/static/rewards/records.png" mode="aspectFit" aria-hidden="true" /><text>兑换记录</text></button><button class="ui-button reward-entry" aria-label="积分商城" @click="go('rewards/mall')"><image class="reward-entry-icon" src="/static/rewards/mall.png" mode="aspectFit" aria-hidden="true" /><text>积分商城</text></button><button class="ui-button reward-entry" aria-label="活动中心" @click="go('content/activities')"><image class="reward-entry-icon" src="/static/rewards/activities.png" mode="aspectFit" aria-hidden="true" /><text>活动中心</text></button></view></view><view class="profile-promos"><button class="ui-button" @click="open('certification/index')"><text class="bold">{{session.user?.playerProfile?.shopStatus==='APPROVED'?'我的店铺':'认证店铺'}}</text><text class="tiny">资料披露 · 出售必需</text><view class="promo-art"><AppIcon class="app-icon" name="game" :size="38" /></view></button><button class="ui-button" @click="open('manage/index',{kind:'SERVICE'})"><text class="bold">我的商品</text><text class="tiny">管理在售道具</text><view class="promo-art"><AppIcon class="app-icon" name="clipboard" :size="34" /></view></button></view><view class="card section"><view class="list-row" @click="open('identity/index')"><AppIcon name="shield" /><text class="flex-1">实名认证</text><text class="muted tiny">{{session.user?.playerProfile?.realnameStatus==='VERIFIED'?'已实名':'未实名'}}</text><AppIcon name="chevron" :size="15" /></view><view class="list-row" @click="go('players/search')"><AppIcon name="search" /><text class="flex-1">按编号查找玩家</text><AppIcon name="chevron" :size="15" /></view><view class="list-row" @click="open('certification/index')"><AppIcon class="app-icon" name="shield" /><text class="flex-1">店铺认证</text><text class="muted tiny">{{labels[session.user?.playerProfile?.shopStatus||'NONE']}}</text><AppIcon class="app-icon" name="chevron" :size="15" /></view><view class="list-row" @click="go('account/index',{type:'help'})"><AppIcon class="app-icon" name="headset" /><text>帮助与客服</text><AppIcon class="app-icon" name="chevron" :size="15" /></view><view class="list-row" @click="open('account/index',{type:'settings'})"><AppIcon class="app-icon" name="settings" /><text>设置</text><AppIcon class="app-icon" name="chevron" :size="15" /></view></view><text v-if="error" class="field-error">{{error}}</text><button v-if="!session.token" class="ui-button btn wide" @click="go('auth/index')">登录 / 注册</button></view></AppShell></template>

<script setup>

import {loadSite,contentImage} from '../../lib/content';import {ref,computed} from 'vue';import PlayerBadges from '../../components/PlayerBadges.vue';import {onShow} from '@dcloudio/uni-app';import AppShell from '../../components/AppShell.vue';import AppIcon from '../../components/AppIcon.vue';import GameArt from '../../components/GameArt.vue';import {session,loadMe,requireLogin,go,money,labels,toast} from '../../lib/api';const site=ref(null),error=ref(''),openingHome=ref(false);const profile=computed(()=>session.user?.playerProfile||{}),membershipDate=computed(()=>profile.value.membershipExpiresAt?String(profile.value.membershipExpiresAt).replace('T',' ').slice(0,10):'待更新');const stats=[{type:'favorites',key:'favorites',label:'收藏'},{type:'history',key:'history',label:'浏览'},{type:'follows',key:'follows',label:'关注'},{type:'coupons',key:'coupons',label:'优惠券'}],transactions=[{label:'我的求购',icon:'send',path:'manage/index',params:{kind:'REQUEST'}},{label:'我卖出的',icon:'clipboard',path:'orders/index',params:{role:'worker'}},{label:'我买到的',icon:'bag',path:'orders/index'},{label:'售后服务',icon:'shield',path:'orders/index',params:{status:'AFTERSALE'}}];async function openHome(){if(openingHome.value||!requireLogin())return;const token=session.token;openingHome.value=true;try{if(!session.user?.id)await loadMe();if(token!==session.token||!session.user?.id)return;go('shop/index',{id:session.user.id})}catch(e){if(token===session.token){error.value=e.message;toast(e.message)}}finally{openingHome.value=false}}function open(path,params){if(requireLogin())go(path,params)}onShow(async()=>{try{await loadMe();site.value=await loadSite();error.value=''}catch(e){error.value=e.message}})

</script>

<style scoped>.profile-custom-banner{width:100%;height:100%;display:block}.profile-head{padding:26px 16px 0;background:#fff}.profile-avatar{width:58px;height:58px}.profile-name{font-size:19px;font-weight:750}.profile-head>.row{gap:9px}.profile-head .icon-button{width:30px}.profile-head .tag{align-self:flex-start;font-size:10px}.profile-banner{background:#ffe433;border-radius:14px;position:relative;margin-top:22px;height:100px;overflow:hidden;display:flex;align-items:center}.profile-banner .game-art{position:absolute;right:-8px;top:-7px;width:125px;height:125px}.profile-banner>view:last-child{position:relative;padding:15px}.profile-banner text{display:block}.profile-banner .bold{font-size:17px}.profile-banner .tiny{margin-top:5px;color:#796522}.stats{display:flex;padding:22px 0 18px}.stats button{display:flex;flex-direction:column;align-items:center;flex:1;gap:6px;font-size:12px}.stats button>text:first-child{font-size:23px;font-weight:750}.transactions{display:flex;justify-content:space-between;gap:6px}.transactions button{display:flex;flex-direction:column;align-items:center;gap:9px;font-size:12px;min-width:58px}.wallet-number{font-size:30px;font-weight:750;color:var(--red)}.profile-promos{display:grid;grid-template-columns:1fr 1fr;gap:10px}.profile-promos button{height:102px;border-radius:12px;background:#ffe433;padding:14px;text-align:left;position:relative;overflow:hidden}.profile-promos button:nth-child(2){background:#c3ddff}.profile-promos text{display:block}.profile-promos .tiny{font-size:10px;margin-top:4px;color:#5d616c}.profile-promos .app-icon{position:absolute;right:8px;bottom:5px;opacity:.65}.profile-head{padding:20px 16px 0}.profile-name{font-size:18px}.profile-banner{margin-top:16px;height:106px;border-radius:12px}.profile-banner .bold{font-size:19px}.stats{padding:13px 0 12px}.stats button{gap:2px}.stats button>text:first-child{font-size:21px}.profile-promos button{height:82px;padding:12px}.profile-promos .app-icon{right:10px;bottom:13px}.profile-promos .bold{font-size:15px}.profile-head+.pad{padding-top:10px}.card .section-heading{margin-bottom:8px}.transactions button{gap:6px;font-size:11px}.wallet-number{font-size:30px}.card.section{margin-top:12px}.promo-art{position:absolute;right:10px;bottom:13px;opacity:.75}.profile-promos .promo-art .app-icon{position:static;opacity:1}/* #ifdef MP-WEIXIN */.profile-head{padding-top:54px}/* #endif */.profile-promos .tiny{max-width:calc(100% - 40px);line-height:1.45;white-space:normal}.profile-banner .profile-banner-copy{max-width:calc(100% - 114px);box-sizing:border-box;padding:12px 15px}.profile-banner .bold{font-size:18px;line-height:1.25;white-space:normal}.avatar-home{display:flex;align-items:center;justify-content:center;flex-shrink:0;width:58px;height:58px;padding:0;border-radius:50%}.avatar-home:focus-visible{outline:2px solid var(--ink);outline-offset:3px}.profile-avatar{cursor:pointer}.reward-entries{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:4px}.reward-entries .reward-entry{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:8px;min-width:0;width:100%;min-height:80px;padding:6px 0;text-align:center;font-size:12px;line-height:20px;white-space:nowrap;border-radius:8px}.reward-entry-icon{display:block;width:44px;height:44px;flex-shrink:0}.reward-entry:focus-visible{outline:2px solid var(--ink);outline-offset:2px}.benefit-cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px;margin-bottom:12px;align-items:stretch}.benefit-cards .card{min-width:0;width:100%;margin:0}.benefit-details{padding:0;overflow:hidden}.benefit-card{display:flex;flex-direction:column;width:100%;min-width:0;padding:12px 14px;text-align:left;white-space:normal;line-height:1.5}.growth-card{min-height:90px}.membership-card{min-height:68px;border-top:1px solid #f0f1f3}.benefit-card>.row,.wallet-card>.row{width:100%;gap:4px}.benefit-label{font-size:13px;font-weight:600;flex:1}.benefit-level{font-size:15px;font-weight:750}.benefit-value{font-size:12px;line-height:1.5;white-space:nowrap}.benefit-caption{display:block;margin-top:6px;font-size:12px;color:var(--muted);overflow-wrap:anywhere}.benefit-progress{width:100%;height:5px;margin-top:8px}.benefit-hint{display:block;margin-top:auto;padding-top:8px;font-size:11px;color:var(--muted)}.member-active{background:#fff3a5;border-radius:4px;padding:0 3px}.wallet-card{display:flex;flex-direction:column;padding:14px;text-align:left;line-height:1.5;white-space:normal}.wallet-card .wallet-number{display:block;margin-top:18px;font-size:27px;font-weight:750;line-height:1.25;overflow-wrap:anywhere;font-variant-numeric:tabular-nums}.benefit-card:focus-visible,.wallet-card:focus-visible{outline:2px solid var(--ink);outline-offset:-3px}.benefit-card:active,.wallet-card:active{background:#fffbea}</style>





